248	// ListProviders returns providers known to the native-agent harness with live
249	// status, configured-default markers, and cooldown state.
250	func (s *service) ListProviders(ctx context.Context) ([]ProviderInfo, error) {
251		sc := s.opts.ServiceConfig
252		if sc == nil {
253			return nil, fmt.Errorf("service: no ServiceConfig provided; pass ServiceOptions.ServiceConfig")
254		}
255	
256		names := sc.ProviderNames()
257		defaultName := sc.DefaultProviderName()
258		cooldown := sc.HealthCooldown()
259		if cooldown <= 0 {
260			cooldown = 30 * time.Second
261		}
262	
263		type indexedInfo struct {
264			idx  int
265			info ProviderInfo
266		}
267		results := make([]indexedInfo, len(names))
268		var wg sync.WaitGroup
269	
270		for i, name := range names {
271			wg.Add(1)
272			go func(idx int, name string) {
273				defer wg.Done()
274	
275				entry, ok := sc.Provider(name)
276				if !ok {
277					results[idx] = indexedInfo{idx: idx, info: ProviderInfo{
278						Name:   name,
279						Status: "error: provider not found in config",
280					}}
281					return
282				}
283	
284				info := ProviderInfo{
285					Name:         name,
286					Type:         normalizeServiceProviderType(entry.Type),
287					BaseURL:      entry.BaseURL,
288					Endpoints:    append([]ServiceProviderEndpoint(nil), entry.Endpoints...),
289					IsDefault:    name == defaultName,
290					DefaultModel: entry.Model,
291				}
292	
293				probeCtx, cancel := context.WithTimeout(ctx, 5*time.Second)
294				defer cancel()
295				capturedAt := time.Now().UTC()
296				probe := probeProviderStatus(probeCtx, entry, capturedAt)
297				info.Status = probe.status
298				info.ModelCount = probe.modelCount
299				info.Capabilities = probe.caps
300				info.CooldownState = serviceProviderCooldown(sc, name, cooldown)
301				info.Auth = providerAuthStatus(entry, info.Status, capturedAt)
302				info.EndpointStatus = probe.endpointStatuses
303				info.Quota = providerQuotaState(entry, capturedAt)
304				lastErrorSource := "service provider config"
305				if len(info.EndpointStatus) > 0 {
306					lastErrorSource = info.EndpointStatus[0].Source
307				}
308				info.LastError = statusErrorDetail(info.Status, probe.detail, lastErrorSource, capturedAt)
309	
310				results[idx] = indexedInfo{idx: idx, info: info}
311			}(i, name)
312		}
313		wg.Wait()
314	
315		out := make([]ProviderInfo, len(names))
316		for _, r := range results {
317			out[r.idx] = r.info
318		}
319		return out, nil
320	}
