322	// HealthCheck triggers a fresh probe for the named target and updates internal state.
323	// target.Type is "harness" or "provider".
324	func (s *service) HealthCheck(ctx context.Context, target HealthTarget) error {
325		switch target.Type {
326		case "provider":
327			sc := s.opts.ServiceConfig
328			if sc == nil {
329				return fmt.Errorf("service: no ServiceConfig provided; pass ServiceOptions.ServiceConfig")
330			}
331			entry, ok := sc.Provider(target.Name)
332			if !ok {
333				return fmt.Errorf("service: provider %q not found", target.Name)
334			}
335			probeCtx, cancel := context.WithTimeout(ctx, 5*time.Second)
336			defer cancel()
337			probe := probeProviderStatus(probeCtx, entry, time.Now().UTC())
338			if probe.status == "connected" {
339				return nil
340			}
341			msg := probe.status
342			if probe.detail != "" {
343				msg = probe.detail
344			}
345			return fmt.Errorf("service: provider %q: %s", target.Name, msg)
346	
347		case "harness":
348			statuses := s.registry.Discover()
349			for _, st := range statuses {
350				if st.Name != target.Name {
351					continue
352				}
353				if !st.Available {
354					return fmt.Errorf("service: harness %q unavailable: %s", target.Name, st.Error)
355				}
356				// For subscription harnesses, refresh the quota cache when stale.
357				if target.Name == "claude" {
358					healthCheckRefreshClaudeQuota(ctx)
359				}
360				if target.Name == "codex" {
361					healthCheckRefreshCodexQuota(ctx)
362				}
363				return nil
364			}
365			return fmt.Errorf("service: harness %q not registered", target.Name)
366	
367		default:
368			return fmt.Errorf("service: unknown HealthTarget.Type %q (want \"harness\" or \"provider\")", target.Type)
369		}
370	}
