372	// probeServiceProvider pings a provider and returns (status, modelCount, capabilities).
373	func probeServiceProvider(ctx context.Context, entry ServiceProviderEntry) (status string, modelCount int, caps []string) {
374		probe := probeServiceProviderDetailed(ctx, entry)
375		return probe.status, probe.modelCount, probe.caps
376	}
