378	func probeServiceProviderDetailed(ctx context.Context, entry ServiceProviderEntry) providerProbeResult {
379		switch entry.Type {
380		case "anthropic":
381			if entry.APIKey == "" {
382				return providerProbeResult{status: "error: api_key not configured", detail: "api_key not configured"}
383			}
384			// Anthropic does not expose an unauthenticated /v1/models list endpoint.
385			// Treat key presence as the connectivity signal.
386			return providerProbeResult{status: "connected", caps: providerCapabilities(entry)}
387	
388		case "openai", "openrouter", "lmstudio", "omlx", "ollama", "minimax", "qwen", "zai", "":
389			if entry.BaseURL == "" {
390				return providerProbeResult{status: "error: base_url not configured", detail: "base_url not configured"}
391			}
392			n, err := discoverOpenAIModels(ctx, entry.BaseURL, entry.APIKey)
393			if err != nil {
394				msg := err.Error()
395				if serviceIsUnreachable(msg) {
396					return providerProbeResult{status: "unreachable", detail: serviceTrimError(msg)}
397				}
398				detail := serviceTrimError(msg)
399				return providerProbeResult{status: "error: " + detail, detail: detail}
400			}
401			return providerProbeResult{status: "connected", modelCount: n, caps: providerCapabilities(entry)}
402	
403		default:
404			detail := "unknown provider type " + entry.Type
405			return providerProbeResult{status: "error: " + detail, detail: detail}
406		}
407	}
