409	func probeProviderStatus(ctx context.Context, entry ServiceProviderEntry, capturedAt time.Time) providerProbeResult {
410		endpoints := modelDiscoveryEndpoints(entry)
411		if len(endpoints) == 0 {
412			probe := probeServiceProviderDetailed(ctx, entry)
413			probe.endpointStatuses = providerEndpointStatusesFromProbe(entry, probe, capturedAt)
414			return probe
415		}
416	
417		statuses := make([]EndpointStatus, 0, len(endpoints))
418		var aggregate providerProbeResult
419		aggregate.status = "error: endpoint probe did not run"
420		for _, endpoint := range endpoints {
421			endpointEntry := entry
422			endpointEntry.BaseURL = endpoint.BaseURL
423			endpointProbe := probeServiceProviderDetailed(ctx, endpointEntry)
424			endpointProbe.endpointName = endpoint.Name
425			endpointProbe.baseURL = endpoint.BaseURL
426			statuses = append(statuses, endpointStatusFromProbe(endpoint.Name, endpoint.BaseURL, endpointProbe, capturedAt))
427			if endpointProbe.status == "connected" {
428				if aggregate.status != "connected" {
429					aggregate.status = "connected"
430					aggregate.caps = append([]string(nil), endpointProbe.caps...)
431					aggregate.detail = ""
432				}
433				aggregate.modelCount += endpointProbe.modelCount
434				continue
435			}
436			if aggregate.status == "connected" {
437				continue
438			}
439			if shouldPreferProviderProbe(endpointProbe, aggregate) {
440				aggregate.status = endpointProbe.status
441				aggregate.detail = endpointProbe.detail
442				aggregate.caps = append([]string(nil), endpointProbe.caps...)
443				aggregate.baseURL = endpointProbe.baseURL
444				aggregate.endpointName = endpointProbe.endpointName
445			}
446		}
447		aggregate.endpointStatuses = statuses
448		return aggregate
449	}
