468	// discoverOpenAIModels queries the /v1/models endpoint and returns the model count.
469	// This is a minimal inline version of provider/openai.DiscoverModels that avoids
470	// the import cycle (provider/openai imports the root agent package).
471	func discoverOpenAIModels(ctx context.Context, baseURL, apiKey string) (int, error) {
472		base := strings.TrimRight(baseURL, "/")
473		endpoint := base + "/models"
474	
475		req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
476		if err != nil {
477			return 0, fmt.Errorf("discovery: build request: %w", err)
478		}
479		req.Header.Set("Accept", "application/json")
480		if apiKey != "" {
481			req.Header.Set("Authorization", "Bearer "+apiKey)
482		}
483	
484		resp, err := http.DefaultClient.Do(req)
485		if err != nil {
486			return 0, err
487		}
488		defer resp.Body.Close()
489	
490		if resp.StatusCode != http.StatusOK {
491			body, _ := io.ReadAll(io.LimitReader(resp.Body, 512))
492			return 0, fmt.Errorf("discovery: %s returned HTTP %d: %s", endpoint, resp.StatusCode, strings.TrimSpace(string(body)))
493		}
494	
495		var mr struct {
496			Data []struct {
497				ID string `json:"id"`
498			} `json:"data"`
499		}
500		if err := json.NewDecoder(resp.Body).Decode(&mr); err != nil {
501			return 0, fmt.Errorf("discovery: decode response from %s: %w", endpoint, err)
502		}
503		return len(mr.Data), nil
504	}
