506	// serviceProviderCooldown scans all model routes for any candidate matching
507	// providerName and returns the first active CooldownState, or nil.
508	func serviceProviderCooldown(sc ServiceConfig, providerName string, cooldown time.Duration) *CooldownState {
509		workDir := sc.WorkDir()
510		if workDir == "" {
511			return nil
512		}
513		now := time.Now().UTC()
514		for _, routeName := range sc.ModelRouteNames() {
515			for _, candidate := range sc.ModelRouteCandidates(routeName) {
516				if candidate != providerName {
517					continue
518				}
519				failures := serviceLoadRouteFailures(workDir, routeName)
520				failedAt, hasFail := failures[providerName]
521				if !hasFail {
522					continue
523				}
524				until := failedAt.Add(cooldown)
525				if until.Before(now) {
526					continue
